import re
from auto_config.generator.utils.logger import logger


def profile_to_device_type(profile_arg):
    default_fsm_type = "FSM5"
    fsm_type_to_profile = {
        "FSM3": ["_FCC_", "_2FCC_"],
        "FSM4": ["_R4A_", "_R4AAA_"],
        "FSM6": ["_ASOF_", "_R4E12_", "_R4OE12_", "_E_", "_ASOG_", "_ASOH_"],
    }
    for fsm_key, profiles in fsm_type_to_profile.items():
        for profile_part in profiles:
            if profile_part in profile_arg:
                return fsm_key
    return default_fsm_type


def validate_type(device_type):
    """
        hw_to_fsm_type_map = {
        'FSMF': 'FSM3',
        'ASIA': 'FSM4',
        'ASIB': 'FSM5',
        'ASIL': 'FSM5',
        'ASIM': 'FSM5',
        'ASOE': 'FSM6',
        'ASOF': 'FSM6',
        'ASOG': 'FSM6',
        'ASOH': 'FSM6'
        'VNFC': 'VNFC'
    }
    """

    if re.match(r"FSM[3-6]$", device_type):
        return device_type

    if device_type == "FSMF":
        return "FSM3"

    if device_type == "ASIA":
        return "FSM4"

    if device_type in ("ASIB", "ASIL", "ASIM"):
        return "FSM5"

    if re.match(r"ASO.*", device_type):
        return "FSM6"

    if device_type == "VNFC":
        return "VNFC"

    logger.info(
        "Not supported device_type. Supported Types: "
        "FSM3, FSM4, FSM5, FSM6, FSMF, ASIA, ASIB, ASIL, ASOE, ASOF, ASOG, ASOH, VNFC"
    )
    raise KeyError


def get_cus_hardware_platform(profile):
    if (
        profile.endswith("CUS_LO")
        or profile.endswith("CUS_LOOO")
        or profile.endswith("CUS_LO_TDD")
        or profile.endswith("CUS_LOOO_TDD")
        or profile.endswith("SIM_LO")
        or profile.endswith("SIM_LO_TDD")
        or profile.endswith("CUS_LO_XGEN_ECPRI")
        or profile.endswith("CUS_LO_XGEN_ECPRI_TDD")
    ):
        return "CUS2"
    elif ("CUS_MP" in profile):
        return "CUS3"
    return "FSMR4"


def get_full_rack(profile):
    if ("2MPPP_2CUS_MPPP" in profile):
        return True
    return False


def get_execution_config(
    build, is_perf, device_type, profile, vlan_id, root_key, service_key
):

    logger.info(f"Profile: {profile}")

    if device_type:
        fsm_type = validate_type(device_type.upper())
        logger.info(f"FSM Type: {fsm_type}")
    else:
        fsm_type = profile_to_device_type(profile)
        logger.info(f"FSM Type from profile: {fsm_type}")
    logger.info(f"Build: {build}")
    if vlan_id:
        logger.info(f"Vlan ID: {vlan_id}")

    configuration_type = "PET" if is_perf else "ET"
    logger.info(f"Configuration type: {configuration_type}")

    cus_hardware_platform = get_cus_hardware_platform(profile)
    logger.info(f"CUS Hardware Platform: {cus_hardware_platform}")

    full_rack = get_full_rack(profile)
    logger.info(f"Full Rack: {full_rack}")

    return {
        "fsm_type": fsm_type,
        "pddb_default_dir": "/opt/emssim/pddb/",
        "is_fsm3": fsm_type == "FSM3",
        "is_fsm4": fsm_type in ("FSM4", "FSM5", "FSM6"),
        "is_fsm5": fsm_type in ("FSM5", "FSM6"),
        "is_fsm6": fsm_type == "FSM6",
        "is_sran": bool(re.match(r"(SBTS|FL00)", build)) if build else True,
        "is_fullrack": full_rack,
        "configuration_type": configuration_type,
        "hardware_platform": cus_hardware_platform,
        "vlan_id": vlan_id,
        "root_key": root_key,
        "service_key": service_key,
    }
